using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 no longer uses "Discriminator" property
            // for non-hierarchical containers. Existing documents have this property,
            // so we must opt back in explicitly.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Breaking change 2: EF Core 9 uses only the key for the id property
            // instead of "Discriminator|Key". Existing documents use the old format,
            // so we preserve it with an id factory.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<BlogIdGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF.
            // HasIndex() now throws in EF Core 9. Remove it.
            // (was: entity.HasIndex(b => b.Name);)
        });
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

